#[derive(Debug, Clone)]
pub struct Item {
    pub price: f64,
    pub qty: u32,
}

pub fn calc_total(items: &[Item]) -> f64 {
    items.iter().map(|i| i.price * i.qty as f64).sum()
}

pub fn format_price(amount: f64) -> String {
    format!("${:.2}", amount)
}

